// ===== DONNÉES DE TEST (à remplacer plus tard par le state.json de l'Architecte) =====
const meta = {
  these_centrale: "L'IA locale rend la souveraineté numérique accessible aux indépendants et PME, sans budget datacenter.",
  ton: "Pédagogue, direct, ancré dans la pratique. Posture d'apprenant curieux, jamais de ton donneur de leçons.",
  public_cible: "Professionnels non-techniciens curieux d'IA, dirigeants de petites structures",
  interdits: ["jargon non expliqué", "promesses non sourcées", "ton commercial"]
};

const terminologie = {
  "modèle open-weight": "modèle dont les poids sont téléchargeables et exécutables localement, sans que le code d'entraînement soit forcément public",
  "inférence": "le fait de faire tourner un modèle pour produire une réponse"
};

const chapitre = {
  numero: 1,
  titre: "Pourquoi faire tourner une IA chez soi change tout",
  objectif: "Le lecteur comprend les 3 raisons concrètes (confidentialité, coût, contrôle) de préférer une IA locale, et sait juger si c'est pertinent pour son cas.",
  points_cles: [
    "La confidentialité : aucune donnée ne quitte la machine, exemples concrets (documents clients, données santé, stratégie)",
    "Le coût : comparaison abonnement API vs matériel amorti, ordre de grandeur chiffré",
    "Le contrôle : pas de modèle retiré du jour au lendemain, pas de changement de conditions",
    "Les limites honnêtes : qualité inférieure au frontier, matériel nécessaire",
    "Grille de décision simple : dans quels cas local, dans quels cas API"
  ]
};

const resumes_precedents = "(aucun — premier chapitre)";

return [{ json: { meta, terminologie, chapitre, resumes_precedents, iteration: 2, critiques_eventuelles: "Verdict : L'auteure a établi un bon équilibre entre clarté et profondeur des idées, tout en soulignant les faiblesses de l'approche API.\nPassage faible : \"Imaginez le cas concret d’une PME de conseil juridique. Ses dossiers contiennent des informations clients hyper-sensibles, soumises au secret professionnel.\" → Ce passage est ambigu et ne claire pas la problématique.\nPassage faible : \"Le fait d’exécuter le processus d’inférence localement signifie que rien, absolument rien, ne quitte votre machine ou votre réseau privé.\" → L'extraction est incomplète et ne met pas en lumière la faiblesse relative à une IA API.\nPassage faible : \"Le coût cumulé des API peut dépasser très rapidement le prix d’une bonne carte graphique dédiée ou d’un mini-ordinateur puissant (type NUC) adapté au calcul local.\" → L'extraction est incomplète et ne met pas en lumière la faiblesse relative à une IA API.\nPassage faible : \"Le risque n’est pas nécessairement une intention malveillante de la part du fournisseur (bien qu'il faille toujours rester vigilant),\" → Ce passage est ambigu et ne claire pas la problématique." } }];

// ===== CONSTRUCTION DU BODY POUR LE RÉDACTEUR (gemma3:12b) =====
const d = $json;

const system = `Tu es écrivain professionnel. Tu rédiges UN chapitre de livre, en français, d'après un plan strict.

RÈGLES ABSOLUES :
1. Tu rédiges UNIQUEMENT le chapitre demandé. Pas d'introduction du type "Voici le chapitre", pas de commentaire, pas de conclusion méta. Ta réponse commence directement par le titre du chapitre en niveau markdown ## et continue en prose.
2. Tu couvres TOUS les points_cles du plan, dans un ordre logique, sans en ajouter d'autres.
3. Tu respectes la these_centrale et le ton définis dans le contexte. Tu n'utilises jamais les éléments listés dans "interdits".
4. Tu utilises la terminologie EXACTEMENT comme définie dans le glossaire fourni. Si tu introduis un terme technique nouveau, tu le définis à sa première occurrence.
5. Cohérence : tu ne répètes pas ce que les résumés des chapitres précédents indiquent comme déjà traité. Tu peux y faire référence brièvement ("comme vu au chapitre 3").
6. Longueur : entre 1500 et 2500 mots.
7. Structure : prose fluide dominante. Maximum 2 listes à puces dans tout le chapitre. Sous-titres (###) toutes les 400-600 mots environ.
8. Chaque affirmation chiffrée ou factuelle précise est marquée [VERIF] juste après. Exemple : "le marché a triplé en cinq ans [VERIF]".
9. SI des critiques te sont fournies (mode reprise) : tu réécris le chapitre en corrigeant CHAQUE point critiqué. Tu ne te contentes pas de retouches cosmétiques.`;

const prompt = `CONTEXTE DU LIVRE :
Thèse centrale : ${d.meta.these_centrale}
Ton : ${d.meta.ton}
Public : ${d.meta.public_cible}
Interdits : ${d.meta.interdits.join(", ")}
Terminologie : ${JSON.stringify(d.terminologie, null, 2)}

RÉSUMÉS DES CHAPITRES PRÉCÉDENTS :
${d.resumes_precedents}

PLAN DU CHAPITRE À RÉDIGER :
Numéro : ${d.chapitre.numero}
Titre : ${d.chapitre.titre}
Objectif : ${d.chapitre.objectif}
Points clés à couvrir :
${d.chapitre.points_cles.map((p, i) => `${i + 1}. ${p}`).join("\n")}

${d.critiques_eventuelles ? "CRITIQUES À CORRIGER (mode reprise) :\n" + d.critiques_eventuelles + "\n\n" : ""}Rédige le chapitre.`;

return [{ json: {
  model: "gemma4:e4b",
  system,
  prompt,
  stream: false,
  options: { temperature: 0.8, num_ctx: 16384 }
} }];

// ===== CONSTRUCTION DU BODY POUR LE CRITIQUE (mistral:7b, format json) =====
const texteChapitre = $json.response; // sortie Ollama du Rédacteur
const d = $('Données de test').first().json;

const system = `Tu es un critique littéraire et éditorial impitoyable mais juste. Tu évalues UN chapitre contre son plan.

RÈGLES ABSOLUES :
1. Tu réponds UNIQUEMENT avec un objet JSON valide conforme au schéma. Aucun texte hors JSON.
2. Tu notes chaque axe de 1 à 10. Un 8+ signifie "publiable tel quel sur cet axe". Sois sévère : la moyenne attendue d'un premier jet est 6.
3. Pour "passages_faibles", tu cites EXACTEMENT 3 extraits textuels (10-30 mots chacun, copiés verbatim du chapitre) avec la raison de leur faiblesse. C'est obligatoire même si le chapitre est bon.
4. "couverture_plan" : tu listes chaque point_cle du plan avec true/false selon qu'il est réellement traité (pas juste mentionné).
5. Tu ne proposes PAS de réécriture. Tu diagnostiques, c'est tout.
6. Tu évalues en français.

SCHÉMA :
{
  "scores": {"clarte": int, "tenue_objectif": int, "non_redondance": int, "respect_ton": int, "densite_valeur": int},
  "couverture_plan": [{"point_cle": string, "couvert": boolean}],
  "passages_faibles": [{"extrait": string, "probleme": string}],
  "verdict_une_phrase": string
}`;

const prompt = `PLAN DU CHAPITRE :
Objectif : ${d.chapitre.objectif}
Points clés attendus :
${d.chapitre.points_cles.map((p, i) => `${i + 1}. ${p}`).join("\n")}
Ton attendu : ${d.meta.ton}

RÉSUMÉS DES CHAPITRES PRÉCÉDENTS (pour juger la redondance) :
${d.resumes_precedents}

CHAPITRE À ÉVALUER :
${texteChapitre}

Évalue.`;

return [{ json: {
  model: "deepseek-r1:7b",
  system,
  prompt,
  stream: false,
  format: "json",
  options: { temperature: 0.2, num_ctx: 16384 },
  _texte_chapitre: texteChapitre
} }];

// ===== GATE DÉTERMINISTE v2 — blindé pour modèles de raisonnement =====
let brut = $json.response || "";

// 1. Retirer les blocs de réflexion de deepseek-r1
brut = brut.replace(/<think>[\s\S]*?<\/think>/g, "").trim();

// 2. Extraire le premier objet JSON complet trouvé dans le texte
let evaluation = null;
const debut = brut.indexOf("{");
const fin = brut.lastIndexOf("}");
if (debut !== -1 && fin > debut) {
  try {
    evaluation = JSON.parse(brut.substring(debut, fin + 1));
  } catch (e) { /* on gère plus bas */ }
}

// 3. Vérifier que le schéma attendu est présent
const schemaOK = evaluation
  && evaluation.scores
  && typeof evaluation.scores === "object"
  && Object.keys(evaluation.scores).length >= 3;

if (!schemaOK) {
  return [{ json: {
    decision: "erreur_schema_critique",
    message: "Le Critique n'a pas produit le JSON attendu (champ 'scores' absent ou invalide). Voir sortie brute ci-dessous.",
    sortie_brute: brut.substring(0, 2000)
  } }];
}

// 4. Logique de validation (inchangée)
const iteration = $('Données de test').first().json.iteration || 1;
const texteChapitre = $('Préparer requête Critique').first().json._texte_chapitre;

const scores = Object.values(evaluation.scores).filter(v => typeof v === "number");
const moyenne = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 10) / 10;
const minScore = Math.min(...scores);
const planComplet = (evaluation.couverture_plan || []).every(p => p.couvert);

// 5. Contrôles déterministes supplémentaires (les règles vérifiables par code)
const nbMots = texteChapitre.split(/\s+/).length;
const nbPuces = (texteChapitre.match(/^\s*[\*\-]\s+/gm) || []).length;
const anneesSuspectes = texteChapitre.match(/\b20(1[0-9]|2[0-4])\b/g) || [];
const alertes = [];
if (nbMots < 1500 || nbMots > 2600) alertes.push(`Longueur hors cible : ${nbMots} mots`);
if (nbPuces > 8) alertes.push(`Trop de puces : ${nbPuces} lignes`);
if (anneesSuspectes.length) alertes.push(`Années à vérifier : ${[...new Set(anneesSuspectes)].join(", ")}`);

const VALIDE = moyenne >= 8.5 && minScore >= 5 && planComplet;
const MAX_ITERATIONS = 2;

if (VALIDE || iteration >= MAX_ITERATIONS) {
  return [{ json: {
    decision: VALIDE ? "valide" : "valide_avec_reserves",
    moyenne, min_score: minScore, plan_complet: planComplet, iteration,
    nb_mots: nbMots, alertes,
    verdict: evaluation.verdict_une_phrase || "",
    reserves: VALIDE ? [] : (evaluation.passages_faibles || []),
    texte_chapitre: texteChapitre
  } }];
} else {
  const critiques = [
    `Verdict : ${evaluation.verdict_une_phrase || ""}`,
    ...(evaluation.couverture_plan || []).filter(p => !p.couvert).map(p => `Point non traité : ${p.point_cle}`),
    ...(evaluation.passages_faibles || []).map(p => `Passage faible : "${p.extrait}" → ${p.probleme}`),
    ...alertes.map(a => `Contrôle automatique : ${a}`)
  ].join("\n");

  return [{ json: {
    decision: "reprise", moyenne, min_score: minScore, plan_complet: planComplet,
    iteration: iteration + 1, nb_mots: nbMots, alertes, critiques,
    texte_chapitre: texteChapitre
  } }];
}
